package qrcode

import "sort"

// Shift-JIS conversion for Kanji mode. sjisTable is generated by
// internal/sjisgen and checked in, so the library has no runtime dependency.

// toShiftJIS converts every rune of s to its two-byte Shift-JIS form, reporting
// false if any rune is not a JIS X 0208 double-byte character. Kanji mode
// encodes only such pairs, so single-byte (ASCII) runes and the non-JIS X 0208
// table entries (which are not representable in Kanji mode) are rejected.
func toShiftJIS(s string) ([]byte, bool) {
	out := make([]byte, 0, 2*len(s))
	for _, r := range s {
		i := sort.Search(len(sjisTable), func(i int) bool {
			return rune(sjisTable[i]>>16) >= r
		})
		if i == len(sjisTable) || rune(sjisTable[i]>>16) != r {
			return nil, false
		}
		c := uint16(sjisTable[i])
		if !validKanjiCode(c) {
			return nil, false
		}
		out = append(out, byte(c>>8), byte(c))
	}
	return out, true
}

// NewKanjiString returns a Kanji-mode segment for a UTF-8 string, converting it
// to Shift-JIS. It returns ErrInvalidSegment if any rune has no JIS X 0208
// mapping.
func NewKanjiString(s string) (Segment, error) {
	sjis, ok := toShiftJIS(s)
	if !ok {
		return Segment{}, ErrInvalidSegment
	}
	return NewKanji(sjis), nil
}
